/* Reversible operational routing, explicit appointment changes, and visible back controls. */
let dialogContext=null,pageTrail=[],pageScope='';
function navigationScope(){const scope=role+':'+agency;const changed=scope!==pageScope;if(changed){pageScope=scope;pageTrail=[]}return changed}
const navigateBeforeEditor=navigate;navigate=function(v){const changed=navigationScope();if(!changed&&view!==v)pageTrail.push(view);navigateBeforeEditor(v)};
function pageBack(){navigationScope();const previous=pageTrail.pop();if(previous)navigateBeforeEditor(previous)}
const renderBeforeEditor=render;render=function(){navigationScope();renderBeforeEditor();const old=$('#pageBack');if(old)old.remove();if(pageTrail.length){$('header').insertAdjacentHTML('afterbegin','<button id="pageBack" class="secondary" onclick="pageBack()">← Back</button>')}};
const openFormBeforeEditor=openForm;openForm=function(title,content,submit,handler){const parent=modal.open?dialogContext:null;openFormBeforeEditor(title,content,submit,handler);let dirty=false;$('#form')?.addEventListener?.('input',()=>dirty=true);modal.insertAdjacentHTML('beforeend','<div class="actions"><button id="formBack" class="secondary" type="button">← Back / Cancel</button></div>');$('#formBack').onclick=()=>{if(dirty&&!confirm('Discard the unsaved changes in this form?'))return;if(parent?.type==='job')jobDetail(parent.jid,parent.section);else if(parent?.type==='booking')privateBookingDetail(parent.bid);else modal.close()}};
const privateDetailBeforeEditor=privateBookingDetail;privateBookingDetail=function(bid){if(role!=='sevlink')return;privateDetailBeforeEditor(bid);dialogContext={type:'booking',bid};modal.insertAdjacentHTML('afterbegin','<button class="back-link" type="button" onclick="modal.close()">← Back to planner</button>')};
const stageBeforeEditor=jobStage;jobStage=function(j){if(j.routeOverride&&j.status==='New')return j.routeOverride;return stageBeforeEditor(j)};
function editableRoute(j){return !!j&&j.status!=='Completed'&&!j.invoices?.length&&j.sentToSevlink!==false}
function bookingForEdit(jid){return activeJobBooking(jid)||[...state.privateBookings].reverse().find(b=>b.job===jid&&b.status==='Attended')}
function editAttendance(jid){const j=getJob(jid);if(!j||role!=='sevlink'||j.status==='Completed')return;const b=bookingForEdit(jid);if(b)bookingForm(b.id,jid);else if(j.schedule) scheduleForm(jid,true);else bookingForm('',jid)}
const detailBeforeEditor=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeEditor(jid,section);const j=getJob(jid);if(!j)return;dialogContext={type:'job',jid,section};modal.insertAdjacentHTML('afterbegin','<button class="back-link" type="button" onclick="modal.close()">← Back to jobs</button>');if(role!=='sevlink')return;$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="job-controls"><span class="eyebrow">SEVLINK JOB CONTROLS</span><div class="actions"><button class="secondary" onclick="editJobForm('${jid}')">Edit job details / notes</button>${editableRoute(j)?`<button class="secondary" onclick="changeRouteForm('${jid}')">Change route / go back</button><button class="secondary" onclick="editAttendance('${jid}')">${j.schedule?'Edit booking date & time':'Book / edit attendance'}</button>`:''}</div>${j.sevlinkNotes?`<details><summary>Private Sevlink notes</summary><p style="white-space:pre-wrap">${esc(j.sevlinkNotes)}</p></details>`:''}</div>`)};
function editJobForm(jid){const j=getJob(jid);if(!j||role!=='sevlink')return;openForm('Edit Sevlink job details.',`<div class="notice"><b>${esc(property(j.property)?.name)}</b><br>${j.ref} · ${esc(j.title)}</div><label>Job title (shown to the client)</label><input name="title" required maxlength="180" value="${esc(j.title)}"><label>Operational priority</label><select name="priority">${['Normal','High','Urgent'].map(p=>`<option ${p===j.priority?'selected':''}>${p}</option>`).join('')}</select><label>Trade / category</label><select name="category">${Object.keys(guide).map(c=>`<option ${c===j.category?'selected':''}>${c}</option>`).join('')}</select><label>Private Sevlink work notes</label><textarea name="notes" rows="5" maxlength="4000">${esc(j.sevlinkNotes||'')}</textarea><div class="notice">Private notes stay with Sevlink. The original tenant report, quote documents and approvals remain on record.</div>`,'Save job changes',async d=>{if(await saveJobDetails(jid,{title:d.get('title'),priority:d.get('priority'),category:d.get('category'),notes:d.get('notes')})){render();jobDetail(jid);toast('Job details updated.')}})}
async function saveJobDetails(jid,data){const j=getJob(jid);if(!j||role!=='sevlink'||!data.title?.trim()||!['Normal','High','Urgent'].includes(data.priority)||!guide[data.category])return false;return commit(()=>{const sharedChange=j.title!==data.title.trim()||j.priority!==data.priority||j.category!==data.category;j.title=data.title.trim();j.priority=data.priority;j.category=data.category;j.sevlinkNotes=data.notes||'';j.lastStaffEdit={at:now(),by:'Sevlink'};if(sharedChange)addEvent(j,'Job details corrected','Sevlink updated the job title, priority or trade category.');})}
function changeRouteForm(jid,desired=''){const j=getJob(jid);if(role!=='sevlink'||!editableRoute(j))return;const current=jobStage(j),route=desired||(['quoting','assessment','new'].includes(current)?current:'quoting'),hasVisit=!!j.schedule||state.privateBookings.some(b=>b.job===jid&&!['Cancelled','Declined','Attended'].includes(b.status));openForm('Change route / correct a choice.',`<div class="notice"><b>${j.ref} · ${esc(j.title)}</b><br>Current stage: ${esc(stages.find(s=>s[0]===current)?.[1]||j.status)}</div><label>Move this job to</label><select name="route"><option value="new" ${route==='new'?'selected':''}>New requests — review again</option><option value="quoting" ${route==='quoting'?'selected':''}>Quoting — use pictures / job details</option><option value="assessment" ${route==='assessment'?'selected':''}>Assessment & quote — attend first</option></select><label>Reason for correcting the route</label><textarea name="reason" rows="3" required maxlength="1200" placeholder="e.g. Photos are not sufficient; a visit is needed."></textarea>${hasVisit?'<div class="notice">This job has an appointment / private assignment. Returning to an earlier stage will cancel that booking in both calendars. The previous appointment remains in the history.</div><label style="display:flex;align-items:center;gap:10px"><input name="cancelVisit" type="checkbox" style="width:auto" required>I understand the existing appointment will be cancelled and must be rearranged if needed.</label>':''}<div class="notice">Pending quotes will be marked for revision so the wrong version cannot be accepted. Existing approved quotes remain in the record; this action does not approve new spending.</div>`,'Save corrected route',async d=>{if(await moveJobRoute(jid,d.get('route'),d.get('reason'),!!d.get('cancelVisit'))){render();selectedPod=d.get('route');if(view==='overview'||view==='requests')render();jobDetail(jid);toast('Route corrected. Previous actions remain in the history.')}})}
async function moveJobRoute(jid,route,reason,cancelVisit=false){const j=getJob(jid);if(role!=='sevlink'||!editableRoute(j)||!['new','quoting','assessment'].includes(route)||!reason?.trim())return false;const bookings=state.privateBookings.filter(b=>b.job===jid&&!['Cancelled','Declined','Attended'].includes(b.status)),hasVisit=!!j.schedule||bookings.length>0;if(hasVisit&&!cancelVisit){toast('Confirm the effect on the existing appointment before changing the route.');return false}return commit(()=>{j.routeChanges??=[];j.routeChanges.push({at:now(),from:jobStage(j),to:route,reason,oldStatus:j.status});if(hasVisit){if(j.schedule){j.appointmentHistory??=[];j.appointmentHistory.push({...j.schedule,cancelledAt:now(),reason:'Route corrected'});j.previousVisit=j.schedule;j.schedule=null}for(const b of bookings){b.status='Cancelled';b.log.push({at:now(),text:'Cancelled because the job route was corrected.'})}addEvent(j,'Appointment cancelled for route correction','Sevlink will arrange any required replacement attendance.');notify(j,'Appointment update',j.ref+': the previous appointment has been cancelled while Sevlink reviews the next step.')}for(const q of j.quotes)if(q.status==='Pending')q.status='Revision requested by Sevlink';if(route==='quoting'&&j.callout){j.quoteNeeded={status:'Required',notes:reason,at:now(),source:'Operational route correction'}}j.status='New';j.routeOverride=route;j.opsAction=route==='new'?null:route;j.reviewedAt=route==='new'?null:now();j.assigned=true;if(j.team==='Unassigned')j.team='Sevlink Repairs Team';if(route==='assessment'&&j.photoRequest?.status==='Requested')j.photoRequest.status='Superseded by assessment';addEvent(j,'Operational route corrected',({new:'Back to New requests',quoting:'Quote from pictures / job details',assessment:'Attend to assess before quoting'})[route]+'. '+reason);})}
routeQuoting=async function(jid){const j=getJob(jid);if(!j||role!=='sevlink'||!editableRoute(j))return;if(j.schedule||!['new','quoting','assessment'].includes(jobStage(j))){changeRouteForm(jid,'quoting');return}if(await moveJobRoute(jid,'quoting','Sevlink selected remote quoting.')){render();jobDetail(jid);toast('Moved to Quoting. You can change this choice later.')}};
routeAssessment=async function(jid){const j=getJob(jid);if(!j||role!=='sevlink'||!editableRoute(j))return;if(j.schedule||!['new','quoting','assessment'].includes(jobStage(j))){changeRouteForm(jid,'assessment');return}if(await moveJobRoute(jid,'assessment','A visit is needed before quoting.')){render();jobDetail(jid);toast('Moved to Assessment & quote. You can change this choice later.')}};

const completionBeforeEditor=completionForm;
completionForm=function(jid){const j=getJob(jid);if(j?.attendancePurpose==='Assessment'&&['Scheduled','In progress'].includes(j.status)){assessmentFindingsForm(jid);return}return completionBeforeEditor(jid)};
function assessmentFindingsForm(jid){const j=getJob(jid);if(!j||role!=='sevlink'||j.attendancePurpose!=='Assessment'||!['Scheduled','In progress'].includes(j.status))return;openForm('Record assessment findings.',`<p>${esc(property(j.property)?.name)} · ${j.ref}</p><label>Findings / what needs quoting</label><textarea name="findings" required rows="5" maxlength="3000"></textarea><label>Assessment photo (optional)</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><div class="notice">This records the assessment and returns the job to Quoting. It does not mark the repair completed or authorise new spending.</div>`,'Save findings & return to Quoting',async d=>{let photo;try{photo=await fileData(d.get('photo'),imageTypes)}catch(e){toast(e.message);return}if(await saveAssessmentFindings(jid,d.get('findings'),photo)){render();jobDetail(jid,'quotes');toast('Assessment recorded. Prepare the quote.')}})}
async function saveAssessmentFindings(jid,findings,photo){const j=getJob(jid);if(!j||role!=='sevlink'||j.attendancePurpose!=='Assessment'||!['Scheduled','In progress'].includes(j.status)||!findings?.trim())return false;return commit(()=>{j.assessmentFindings={text:findings,at:now()};if(j.schedule){j.appointmentHistory??=[];j.appointmentHistory.push({...j.schedule,status:'Attended'});j.previousVisit=j.schedule;j.schedule=null}for(const b of state.privateBookings.filter(b=>b.job===jid&&b.status==='Accepted')){b.status='Attended';b.log.push({at:now(),text:'Assessment attended; findings recorded.'})}if(photo){photo.phase='before';photo.at=now();j.photos.push(photo);j.beforePhotos.push(photo)}j.status='New';j.opsAction='quoting';j.routeOverride='quoting';if(j.callout)j.quoteNeeded={status:'Required',notes:findings,at:now(),source:'Assessment findings'};j.attendancePurpose=null;addEvent(j,'Assessment completed',findings);j.comments.push({author:'Sevlink',text:'Assessment findings: '+findings,visibility:'shared',at:now()})})}
const finalDetailBeforeEditor=jobDetail;
jobDetail=function(jid,section='comments'){finalDetailBeforeEditor(jid,section);const j=getJob(jid);if(role==='sevlink'&&j?.attendancePurpose==='Assessment'&&$('#complete'))$('#complete').textContent='Record assessment & prepare quote'};
